using namespace std;

/**
 * Description: 各类函数与结构体定义
 * Author: 杜登宇
 */

//加载文件
string load_file(string file_name);

//定义规则结构体
struct rule {
	char left;
	vector<string> right;
	friend ostream& operator << (ostream& out, rule rule);
};
//从文本提取规则、终结符、非终结符、右部
void split_into_rules(const string text, vector<rule>& rules, set<char>& non_terminal, set<char>& terminal, set<string>& right_parts);
//检查规则情况
void check_rules(const vector<rule> rules);
//检查set集情况
template <class T>
void check_set(set<T> set_, string tip);

//定义F（irst/ollow）集结构体
struct F_set {
	bool is_first;
	string left;
	set<char> right;
	friend ostream& operator << (ostream& out, F_set f_set);
};
//查找First集
F_set findFirst(const string right_part, vector<rule> rules);
//查找Follow集
F_set findFollow(const char non_terminal, vector<rule> rules);
//输出一个set集合里存放的字符对应的First集集合
vector<F_set> checkFirst(set<string> right_parts, vector<rule> rules);
//输出一个set集合里存放的字符对应的Follow集集合
vector<F_set> checkFollow(set<char> non_terminal, vector<rule> rules);

//定义LL（1）分析表结构体
struct LL_1_table {
	vector<char> row;
	vector<char> col;
	vector<rule> rules;
	friend ostream& operator << (ostream& out, LL_1_table table);
};
//分析表构建
LL_1_table LL_1(set<char>& terminal, set<char>& non_terminal, vector<rule> rules);
void print_state(stack<char> analysis_s, stack<char> input_s, rule& rule_temp);

//根据分析表进行语法分析
void syntacticAnalysis(LL_1_table table);

/**
* Description: 主函数，简略显示分析过程
* Author: 杜登宇
*/
int main() {
	string file_name = "./test3.txt";

	//调用函式读取文件
	string text = load_file(file_name);

	//预定义变量存放终结符、非终结符、右部以及文法规则
	set<char> non_terminal;
	set<char> terminal;
	set<string> right_parts;
	vector<rule> rules;

	//调用函式对字符串进行终结符、非终结符、右部以及文法规则的提取
	split_into_rules(text, rules, non_terminal, terminal, right_parts);

	//检查提取出来的终结符、非终结符、右部以及文法规则是否正确
	check_rules(rules);
	check_set(right_parts, "提取规则右部");
	check_set(non_terminal, "提取非终结符");
	check_set(terminal, "提取终结符");

	//求右部的First集
//	F_set f = findFirst("AB", rules);
	vector<F_set> first_sets = checkFirst(right_parts, rules);
	//求非终结符的Follow集
	vector<F_set> follow_sets = checkFollow(non_terminal, rules);

	//进行LL（1）分析表的构建
	LL_1_table table = LL_1(terminal, non_terminal, rules);
	//输出分析表
	cout << table;

	//根据构建好的分析表进行语法分析
	syntacticAnalysis(table);

	return 0;
}
/**
 * Description: 函数实现以及各类操作符重载
 * Author: 杜登宇
 **/

string load_file(string file_name) {
	cout << "正在读取文法文件：" << file_name << endl;
	ifstream in(file_name.c_str());
	if (!in) {
		cout << "文法文件打开失败，请检查文件是否存在：" << file_name << endl;
		return "";
	}
	//把文件内容整体流入字符串缓冲区
	stringstream buffer;
	buffer << in.rdbuf();
	in.close();
	string text = buffer.str();
	cout << "文法文件读取成功，文法内容如下：" << endl;
	cout << text << endl << endl;
	return text;
}
ostream& operator << (ostream& out, rule rule) {
	//规则以“左部::=右部1|右部2|...”的形式输出
	out << rule.left << "::=";
	for (unsigned int i = 0; i < rule.right.size(); i++) {
		if (i > 0) {
			out << "|";
		}
		out << rule.right[i];
	}
	return out;
}
void split_into_rules(const string text, vector<rule> &rules, set<char> &non_terminal, set<char> &terminal, set<string> &right_parts) {
	//各条文法规则之间以空白分隔，每条规则形如“左部::=右部1|右部2|...”
	stringstream ss(text);
	string item;
	while (ss >> item) {
		string::size_type pos = item.find("::=");
		if (pos == string::npos || pos == 0) {
			continue;//不是一条合法的产生式，直接忽略
		}
		char left = item[0];
		string rights = item.substr(pos + 3);

		//右部按“|”切分成若干个候选式
		vector<string> parts;
		string part = "";
		for (unsigned int i = 0; i < rights.length(); i++) {
			if (rights[i] == '|') {
				parts.push_back(part);
				part = "";
			}
			else {
				part += rights[i];
			}
		}
		parts.push_back(part);

		//同一个非终结符的产生式可能分开书写，合并到同一条规则中
		int at = -1;
		for (unsigned int i = 0; i < rules.size(); i++) {
			if (rules[i].left == left) {
				at = (int)i;
				break;
			}
		}
		if (at < 0) {
			rule new_rule;
			new_rule.left = left;
			rules.push_back(new_rule);
			at = (int)rules.size() - 1;
		}
		for (unsigned int i = 0; i < parts.size(); i++) {
			if (!parts[i].empty()) {
				rules[at].right.push_back(parts[i]);
			}
		}
		//出现在规则左部的一定是非终结符
		non_terminal.insert(left);
	}

	//所有规则左部都收集完毕之后，再回头区分右部中的终结符和非终结符
	for (unsigned int i = 0; i < rules.size(); i++) {
		for (unsigned int j = 0; j < rules[i].right.size(); j++) {
			const string& part = rules[i].right[j];
			right_parts.insert(part);
			for (unsigned int k = 0; k < part.length(); k++) {
				char c = part[k];
				if (c == '@') {
					continue;//“@”代表空串ε，既不是终结符也不是非终结符
				}
				if (non_terminal.count(c) > 0) {
					continue;
				}
				if (isupper((unsigned char)c)) {
					non_terminal.insert(c);//大写字母一律看作非终结符
				}
				else {
					terminal.insert(c);
				}
			}
		}
	}
}
