static void expect(bool ok, const string& what, const string& got, const string& want) {
	checks++;
	if (!ok) {
		failures++;
		printf("FAIL %s\n  got : %s\n  want: %s\n", what.c_str(), got.c_str(), want.c_str());
	}
}
static void expect_eq(const string& got, const string& want, const string& what) {
	expect(got == want, what, got, want);
}
static string to_s(F_set f) {
	ostringstream os;
	os << f;
	return os.str();
}
static string set_to_s(const set<char>& s) {
	string out;
	for (set<char>::const_iterator it = s.begin(); it != s.end(); it++) {
		if (it != s.begin()) {
			out += ",";
		}
		out += *it;
	}
	return out;
}
//把一段文法文本拆成规则、终结符、非终结符和右部
struct grammar {
	vector<rule> rules;
	set<char> non_terminal;
	set<char> terminal;
	set<string> right_parts;
	grammar(const string text) {
		split_into_rules(text, rules, non_terminal, terminal, right_parts);
	}
};

static const string G1 = "E::=a|b|(T)    T::=EG    G::=,EG|@";
static const string G2 = "E::=AB|a       A::=C|bDA      B::=@     C::=cAD|@     D::=dBe";
static const string G3 = "E::=aH       H::=aMd|d       M::=Ab|@     A::=aM|e";

static void test_split() {
	grammar g(G3);
	expect_eq(set_to_s(g.non_terminal), "A,E,H,M", "G3 non-terminals");
	expect_eq(set_to_s(g.terminal), "a,b,d,e", "G3 terminals");
	ostringstream os;
	for (unsigned int i = 0; i < g.rules.size(); i++) {
		os << g.rules[i] << " ";
	}
	expect_eq(os.str(), "E::=aH H::=aMd|d M::=Ab|@ A::=aM|e ", "G3 rules");

	grammar g1(G1);
	expect_eq(set_to_s(g1.terminal), "(,),,,a,b", "G1 terminals");
	expect_eq(set_to_s(g1.non_terminal), "E,G,T", "G1 non-terminals");
}

static void test_first() {
	grammar g(G3);
	expect_eq(to_s(findFirst("aH", g.rules)), "First(aH)={a}", "G3 First(aH)");
	expect_eq(to_s(findFirst("aMd", g.rules)), "First(aMd)={a}", "G3 First(aMd)");
	expect_eq(to_s(findFirst("d", g.rules)), "First(d)={d}", "G3 First(d)");
	expect_eq(to_s(findFirst("Ab", g.rules)), "First(Ab)={a,e}", "G3 First(Ab)");
	expect_eq(to_s(findFirst("@", g.rules)), "First(@)={@}", "G3 First(@)");
	expect_eq(to_s(findFirst("aM", g.rules)), "First(aM)={a}", "G3 First(aM)");
	expect_eq(to_s(findFirst("e", g.rules)), "First(e)={e}", "G3 First(e)");
	expect_eq(to_s(findFirst("M", g.rules)), "First(M)={@,a,e}", "G3 First(M)");

	grammar g1(G1);
	expect_eq(to_s(findFirst("EG", g1.rules)), "First(EG)={(,a,b}", "G1 First(EG)");
	expect_eq(to_s(findFirst(",EG", g1.rules)), "First(,EG)={,}", "G1 First(,EG)");
	expect_eq(to_s(findFirst("(T)", g1.rules)), "First((T))={(}", "G1 First((T))");
	expect_eq(to_s(findFirst("G", g1.rules)), "First(G)={@,,}", "G1 First(G)");

	//E::=AB 中 A、B 都可以推出空串，因此 First(AB) 里必须含“@”
	grammar g2(G2);
	expect_eq(to_s(findFirst("AB", g2.rules)), "First(AB)={@,b,c}", "G2 First(AB)");
	expect_eq(to_s(findFirst("@", g2.rules)), "First(@)={@}", "G2 First(@)");
	expect_eq(to_s(findFirst("cAD", g2.rules)), "First(cAD)={c}", "G2 First(cAD)");
	expect_eq(to_s(findFirst("bDA", g2.rules)), "First(bDA)={b}", "G2 First(bDA)");
	expect_eq(to_s(findFirst("dBe", g2.rules)), "First(dBe)={d}", "G2 First(dBe)");

	//左递归文法不能把求First集的递归拖入死循环
	grammar left("S::=Sa|b");
	expect_eq(to_s(findFirst("S", left.rules)), "First(S)={b}", "left recursion First(S)");
}

static void test_follow() {
	grammar g(G3);
	expect_eq(to_s(findFollow('E', g.rules)), "Follow(E)={#}", "G3 Follow(E)");
	expect_eq(to_s(findFollow('H', g.rules)), "Follow(H)={#}", "G3 Follow(H)");
	expect_eq(to_s(findFollow('M', g.rules)), "Follow(M)={#,b,d}", "G3 Follow(M)");
	expect_eq(to_s(findFollow('A', g.rules)), "Follow(A)={#,b}", "G3 Follow(A)");

	grammar g1(G1);
	expect_eq(to_s(findFollow('E', g1.rules)), "Follow(E)={#,),,}", "G1 Follow(E)");
	expect_eq(to_s(findFollow('T', g1.rules)), "Follow(T)={#,)}", "G1 Follow(T)");
	expect_eq(to_s(findFollow('G', g1.rules)), "Follow(G)={#,)}", "G1 Follow(G)");

	grammar g2(G2);
	expect_eq(to_s(findFollow('E', g2.rules)), "Follow(E)={#}", "G2 Follow(E)");
	expect_eq(to_s(findFollow('A', g2.rules)), "Follow(A)={#,d,e}", "G2 Follow(A)");
	expect_eq(to_s(findFollow('B', g2.rules)), "Follow(B)={#,e}", "G2 Follow(B)");
	expect_eq(to_s(findFollow('C', g2.rules)), "Follow(C)={#,d,e}", "G2 Follow(C)");
	expect_eq(to_s(findFollow('D', g2.rules)), "Follow(D)={#,d,e}", "G2 Follow(D)");
}

//在分析表中查询一个单元格，返回其中产生式的字符串形式（空单元格返回空串）
static string cell(LL_1_table& t, char nt, char term) {
	int i = -1, j = -1;
	for (unsigned int r = 0; r < t.row.size(); r++) {
		if (t.row[r] == nt) {
			i = (int)r;
		}
	}
	for (unsigned int c = 0; c < t.col.size(); c++) {
		if (t.col[c] == term) {
			j = (int)c;
		}
	}
	if (i < 0 || j < 0) {
		return "?";
	}
	rule r = t.rules[i * t.col.size() + j];
	if (r.right.empty()) {
		return "";
	}
	ostringstream os;
	os << r;
	return os.str();
}

static void test_table() {
	grammar g(G3);
	LL_1_table t = LL_1(g.terminal, g.non_terminal, g.rules);
	//行表头按规则出现顺序排列，第一行就是文法开始符号
	expect_eq(string(t.row.begin(), t.row.end()), "EHMA", "G3 table rows");
	expect_eq(string(t.col.begin(), t.col.end()), "abde#", "G3 table cols");
	expect_eq(cell(t, 'E', 'a'), "E::=aH", "G3 [E,a]");
	expect_eq(cell(t, 'E', 'b'), "", "G3 [E,b] empty");
	expect_eq(cell(t, 'H', 'a'), "H::=aMd", "G3 [H,a]");
	expect_eq(cell(t, 'H', 'd'), "H::=d", "G3 [H,d]");
	expect_eq(cell(t, 'M', 'a'), "M::=Ab", "G3 [M,a]");
	expect_eq(cell(t, 'M', 'e'), "M::=Ab", "G3 [M,e]");
	expect_eq(cell(t, 'M', 'b'), "M::=@", "G3 [M,b]");
	expect_eq(cell(t, 'M', 'd'), "M::=@", "G3 [M,d]");
	expect_eq(cell(t, 'M', '#'), "M::=@", "G3 [M,#]");
	expect_eq(cell(t, 'A', 'a'), "A::=aM", "G3 [A,a]");
	expect_eq(cell(t, 'A', 'e'), "A::=e", "G3 [A,e]");
	expect_eq(cell(t, 'A', 'b'), "", "G3 [A,b] empty");

	grammar g1(G1);
	LL_1_table t1 = LL_1(g1.terminal, g1.non_terminal, g1.rules);
	expect_eq(string(t1.row.begin(), t1.row.end()), "ETG", "G1 table rows");
	expect_eq(cell(t1, 'E', 'a'), "E::=a", "G1 [E,a]");
	expect_eq(cell(t1, 'E', 'b'), "E::=b", "G1 [E,b]");
	expect_eq(cell(t1, 'E', '('), "E::=(T)", "G1 [E,(]");
	expect_eq(cell(t1, 'T', 'a'), "T::=EG", "G1 [T,a]");
	expect_eq(cell(t1, 'T', '('), "T::=EG", "G1 [T,(]");
	expect_eq(cell(t1, 'G', ','), "G::=,EG", "G1 [G,,]");
	expect_eq(cell(t1, 'G', ')'), "G::=@", "G1 [G,)]");
	expect_eq(cell(t1, 'G', '#'), "G::=@", "G1 [G,#]");
	expect_eq(cell(t1, 'G', 'a'), "", "G1 [G,a] empty");
}

int main() {
	test_split();
	test_first();
	test_follow();
	test_table();
	printf("%d checks, %d failures\n", checks, failures);
	return failures == 0 ? 0 : 1;
}

