	ostringstream os;
	for (unsigned int i = 0; i < g.rules.size(); i++) {
		os << g.rules[i] << " ";
	}
	expect_eq(os.str(), "E::=aH H::=aMd|d M::=Ab|@ A::=aM|e ", "G3 rules");

