 **/

string load_file(string file_name) {
	cout << "正在读取文法文件：" << file_name << endl;
	ifstream in(file_name.c_str());
	if (!in) {
		cout << "文法文件打开失败，请检查文件是否存在：" << file_name << endl;
		return "";
	}
	//把文件内容整体流入字符串缓冲区
	stringstream buffer;
	buffer << in.rdbuf();
	in.close();
	string text = buffer.str();
	cout << "文法文件读取成功，文法内容如下：" << endl;
	cout << text << endl << endl;
	return text;
}
ostream& operator << (ostream& out, rule rule) {
	//规则以“左部::=右部1|右部2|...”的形式输出
	out << rule.left << "::=";
	for (unsigned int i = 0; i < rule.right.size(); i++) {
		if (i > 0) {
			out << "|";
		}
		out << rule.right[i];
	}
	return out;
}
void split_into_rules(const string text, vector<rule> &rules, set<char> &non_terminal, set<char> &terminal, set<string> &right_parts) {
	//各条文法规则之间以空白分隔，每条规则形如“左部::=右部1|右部2|...”
	stringstream ss(text);
	string item;
	while (ss >> item) {
		string::size_type pos = item.find("::=");
		if (pos == string::npos || pos == 0) {
			continue;//不是一条合法的产生式，直接忽略
		}
		char left = item[0];
		string rights = item.substr(pos + 3);

		//右部按“|”切分成若干个候选式
		vector<string> parts;
		string part = "";
		for (unsigned int i = 0; i < rights.length(); i++) {
			if (rights[i] == '|') {
				parts.push_back(part);
				part = "";
			}
			else {
				part += rights[i];
			}
		}
		parts.push_back(part);

		//同一个非终结符的产生式可能分开书写，合并到同一条规则中
		int at = -1;
		for (unsigned int i = 0; i < rules.size(); i++) {
			if (rules[i].left == left) {
				at = (int)i;
				break;
			}
		}
		if (at < 0) {
			rule new_rule;
			new_rule.left = left;
			rules.push_back(new_rule);
			at = (int)rules.size() - 1;
		}
		for (unsigned int i = 0; i < parts.size(); i++) {
			if (!parts[i].empty()) {
				rules[at].right.push_back(parts[i]);
			}
		}
		//出现在规则左部的一定是非终结符
		non_terminal.insert(left);
	}

	//所有规则左部都收集完毕之后，再回头区分右部中的终结符和非终结符
	for (unsigned int i = 0; i < rules.size(); i++) {
		for (unsigned int j = 0; j < rules[i].right.size(); j++) {
			const string& part = rules[i].right[j];
			right_parts.insert(part);
			for (unsigned int k = 0; k < part.length(); k++) {
				char c = part[k];
				if (c == '@') {
					continue;//“@”代表空串ε，既不是终结符也不是非终结符
				}
				if (non_terminal.count(c) > 0) {
					continue;
				}
				if (isupper((unsigned char)c)) {
					non_terminal.insert(c);//大写字母一律看作非终结符
				}
				else {
					terminal.insert(c);
				}
			}
		}
	}
}
void check_rules(const vector<rule> rules) {
	//按提取顺序逐条输出文法规则
	cout << "提取文法规则：" << endl;
	if (rules.empty()) {
		//文法文件为空或者书写格式有误时给出提示，避免只打印一个空行
		cout << "    （未提取到任何文法规则，请检查文法文件的书写格式）" << endl << endl;
		return;
	}
	for (unsigned int i = 0; i < rules.size(); i++) {
		cout << "    " << rules[i] << endl;
	}
	cout << endl;
}
template <class T>
void check_set(set<T> set_, string tip) {
	//按集合内部的有序性依次输出各个元素
	cout << tip << "：" << endl;
	cout << "    ";
	if (set_.empty()) {
		//空集合同样给出提示，方便对照检查提取结果
		cout << "（空）" << endl << endl;
		return;
	}
	for (typename set<T>::iterator it = set_.begin(); it != set_.end(); it++) {
		if (it != set_.begin()) {
			cout << "  ";
		}
		cout << *it;
	}
	cout << endl << endl;
}
ostream& operator << (ostream& out, F_set f_set) {
	//根据判别符区分两类集合，形如“First(右部)={a,b}”或者“Follow(非终结符)={#,a}”
	if (f_set.is_first) {
		out << "First(" << f_set.left << ")={";
	}
	else {
		out << "Follow(" << f_set.left << ")={";
	}
	//集合元素之间用逗号分隔
	for (set<char>::iterator it = f_set.right.begin(); it != f_set.right.end(); it++) {
		if (it != f_set.right.begin()) {
			out << ",";
		}
		out << *it;
	}
	out << "}";
	return out;
}
//判断一个字符是否是非终结符：文法中凡是作为规则左部出现过的字符都是非终结符
static bool is_non_terminal(const char c, const vector<rule>& rules) {
	for (unsigned int i = 0; i < rules.size(); i++) {
		if (rules[i].left == c) {
			return true;
		}
	}
	return false;
}
//求符号串ss的First集，visiting记录当前正在展开的非终结符，防止左递归文法导致无限递归
static set<char> firstOf(const string ss, const vector<rule>& rules, set<char>& visiting) {
	set<char> result;
	bool all_epsilon = true;//ss中的每个符号都能推出空串时，First集里才有“@”
	for (unsigned int i = 0; i < ss.length(); i++) {
		char c = ss[i];
		if (c == '@') {
			continue;//“@”本身就代表空串，不影响它后面的符号
		}
		if (!is_non_terminal(c, rules)) {
			result.insert(c);//终结符直接进入First集
			all_epsilon = false;
			break;//终结符后面的符号对First集不再有贡献
		}
		if (visiting.count(c) > 0) {
			all_epsilon = false;
			break;//该非终结符正处在展开过程中，再展开下去就会陷入死循环
		}
		//非终结符：把它的每一个候选式的First集并进来
		visiting.insert(c);
		bool has_epsilon = false;
		for (unsigned int j = 0; j < rules.size(); j++) {
			if (rules[j].left != c) {
				continue;
			}
			for (unsigned int k = 0; k < rules[j].right.size(); k++) {
				set<char> sub = firstOf(rules[j].right[k], rules, visiting);
				for (set<char>::iterator it = sub.begin(); it != sub.end(); it++) {
					if (*it == '@') {
						has_epsilon = true;//该候选式能推出空串，暂不收录“@”
					}
					else {
						result.insert(*it);
					}
				}
			}
		}
		visiting.erase(c);
		if (!has_epsilon) {
			all_epsilon = false;
			break;//该非终结符推不出空串，后面的符号对First集不再有贡献
		}
	}
	if (all_epsilon) {
		result.insert('@');//整个符号串都能推出空串
	}
	return result;
}
F_set findFirst(const string ss, vector<rule> rules) {
	F_set f_set;
	f_set.is_first = true;
	f_set.left = ss;
	set<char> visiting;
	f_set.right = firstOf(ss, rules, visiting);
	return f_set;
}
