// Unit tests for the lexical analyzer helpers.
//
// The lexer is a single translation unit that owns main(), so the source is
// included here with main() renamed out of the way; every helper stays visible.
//
//   g++ -std=c++11 -Wall -o /tmp/lexer_units agent_tests/test_lexer_units.cpp
//   /tmp/lexer_units
#define main lexer_main
#include "../LexicalAnalyzer/LexicalAnalysis.cpp"
#undef main

#include <cstdio>

static int failures = 0;
static int checks = 0;

static void expect_eq(const string& got, const string& want, const string& what) {
	checks++;
	if (got != want) {
		failures++;
		printf("FAIL %s\n  got : %s\n  want: %s\n", what.c_str(), got.c_str(), want.c_str());
	}
}
static void expect_int(int got, int want, const string& what) {
	checks++;
	if (got != want) {
		failures++;
		printf("FAIL %s\n  got : %d\n  want: %d\n", what.c_str(), got, want);
	}
}
static void expect_bool(bool got, bool want, const string& what) {
	expect_eq(got ? "true" : "false", want ? "true" : "false", what);
}

static void test_identifier() {
	expect_bool(IsIdentifier("abc"), true, "IsIdentifier(abc)");
	expect_bool(IsIdentifier("_a1"), true, "IsIdentifier(_a1)");
	expect_bool(IsIdentifier("res1"), true, "IsIdentifier(res1)");
	expect_bool(IsIdentifier("a"), true, "IsIdentifier(a)");
	expect_bool(IsIdentifier("1abc"), false, "IsIdentifier(1abc)");
	expect_bool(IsIdentifier("2res"), false, "IsIdentifier(2res)");
	expect_bool(IsIdentifier(""), false, "IsIdentifier(empty)");
	expect_bool(IsIdentifier("a-b"), false, "IsIdentifier(a-b)");
	expect_bool(IsIdentifier("a b"), false, "IsIdentifier(a b)");
	expect_bool(IsIdentifier("<<"), false, "IsIdentifier(<<)");
}

static void test_num() {
	expect_bool(IsNum("3"), true, "IsNum(3)");
	expect_bool(IsNum("201"), true, "IsNum(201)");
	expect_bool(IsNum("0"), true, "IsNum(0)");
	expect_bool(IsNum("2res"), false, "IsNum(2res)");
	expect_bool(IsNum("12x"), false, "IsNum(12x)");
	//题目要求的判定方式是“首位之后的每一个字符都是数字”，首位本身不参与判断，
	//而wtMatch会先判定标识符，所以这条规则只对以数字打头的单词起作用
	expect_bool(IsNum("1a"), false, "IsNum(1a)");
}

static void test_wtMatch() {
	expect_int(wtMatch("void"), 1, "wtMatch(void)");
	expect_int(wtMatch("main"), 2, "wtMatch(main)");
	expect_int(wtMatch("int"), 3, "wtMatch(int)");
	expect_int(wtMatch("cout"), 4, "wtMatch(cout)");
	expect_int(wtMatch("return"), 5, "wtMatch(return)");
	expect_int(wtMatch("("), 6, "wtMatch(()");
	expect_int(wtMatch(")"), 7, "wtMatch())");
	expect_int(wtMatch("{"), 8, "wtMatch({)");
	expect_int(wtMatch("}"), 9, "wtMatch(})");
	expect_int(wtMatch("<<"), 10, "wtMatch(<<)");
	expect_int(wtMatch(";"), 11, "wtMatch(;)");
	expect_int(wtMatch(","), 12, "wtMatch(,)");
	expect_int(wtMatch("="), 13, "wtMatch(=)");
	expect_int(wtMatch("*"), 14, "wtMatch(*)");
	expect_int(wtMatch("/"), 15, "wtMatch(/)");
	expect_int(wtMatch("a"), 16, "wtMatch(a)");
	expect_int(wtMatch("res1"), 16, "wtMatch(res1)");
	expect_int(wtMatch("_tmp"), 16, "wtMatch(_tmp)");
	expect_int(wtMatch("3"), 17, "wtMatch(3)");
	expect_int(wtMatch("201"), 17, "wtMatch(201)");
	expect_int(wtMatch("2res"), 0, "wtMatch(2res)");
	expect_int(wtMatch("12x"), 0, "wtMatch(12x)");
}

//把一段文本写进临时文件，返回文件名
static string write_temp(const string name, const string content) {
	string path = "/tmp/" + name;
	ofstream out(path.c_str());
	out << content;
	out.close();
	return path;
}

static void test_findError() {
	//行号从1开始、列号从0开始，同一个单词出现多次时逐个报告
	string path = write_temp("lex_units_src.txt", "int a;\nint 2res;\n  2res=1;\n");
	expect_eq(findError(path, "2res"), "第2行第4列第3行第2列", "findError two hits");
	expect_eq(findError(path, "notthere"), "", "findError no hit");
	expect_eq(findError(path, ""), "", "findError empty word");
	expect_eq(findError("/tmp/definitely_missing_file_xyz.txt", "a"), "", "findError missing file");
	//实验给定的源程序中，非法单词2res分别位于第3行第26列和第6行第4列
	expect_eq(findError("../LexicalAnalyzer/testCpp.txt", "2res"), "第3行第26列第6行第4列", "findError on testCpp.txt");
}

