	stringstream buffer2;
	buffer2 << in2.rdbuf();
	in2.close();
	expect_eq(buffer2.str(), "int a; ", "preProcess unterminated comment output");

	expect_bool(preProcess("/tmp/definitely_missing_file_xyz.txt", dst), false, "preProcess missing source");
}

int main() {
	//预处理阶段会向标准输出打印大量提示，测试时把它们丢弃
