#!/usr/bin/env python3
"""Fuzz the LL(1) parser with random small grammars.

For every generated grammar an independent Python model computes FIRST/FOLLOW
(with the project's convention that '#' belongs to every FOLLOW set) and the
LL(1) table.  Grammars whose table has a conflict are skipped — they are not
LL(1), so a table-driven parser is not expected to recognise the language.  For
the rest, the language up to a small length bound is enumerated by brute-force
derivation and compared against the verdict of the compiled parser.

    python3 agent_tests/fuzz_parser.py [num_grammars] [seed]
"""
import itertools
import os
import random
import subprocess
import sys
import tempfile

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
MAX_LEN = 3


def first_of(word, rules, visiting=None):
    """FIRST of a symbol string, matching the C++ firstOf()."""
    visiting = set() if visiting is None else visiting
    out = set()
    all_eps = True
    for c in word:
        if c == "@":
            continue
        if c not in rules:
            out.add(c)
            all_eps = False
            break
        if c in visiting:
            all_eps = False
            break
        visiting.add(c)
        has_eps = False
        for cand in rules[c]:
            sub = first_of(cand, rules, visiting)
            for x in sub:
                if x == "@":
                    has_eps = True
                else:
                    out.add(x)
        visiting.discard(c)
        if not has_eps:
            all_eps = False
            break
    if all_eps:
        out.add("@")
    return out


def follow_of(nt, rules, visiting=None):
    """FOLLOW of a non-terminal, matching the C++ followOf()."""
    visiting = set() if visiting is None else visiting
    out = {"#"}
    visiting.add(nt)
    for left, cands in rules.items():
        for cand in cands:
            for pos, c in enumerate(cand):
                if c != nt:
                    continue
                at_end = True
                if pos + 1 < len(cand):
                    at_end = False
                    for x in first_of(cand[pos + 1 :], rules):
                        if x == "@":
                            at_end = True
                        else:
                            out.add(x)
                if at_end and left not in visiting:
                    out |= follow_of(left, rules, visiting)
    visiting.discard(nt)
    return out


def build_table(rules, order):
    """Return (table, conflict) with table[(nt, terminal)] = candidate."""
    table = {}
    conflict = False
    for left in order:
        for cand in rules[left]:
            heads = set(first_of(cand, rules))
            if "@" in heads:
                heads |= follow_of(left, rules)
            for h in heads:
                if h == "@":
                    continue
                key = (left, h)
                if key in table and table[key] != cand:
                    conflict = True
                table[key] = cand
    return table, conflict


def language(rules, start, max_len):
    seen = {start}
    todo = [start]
    out = set()
    while todo:
        form = todo.pop()
        pos = next((i for i, c in enumerate(form) if c in rules), None)
        if pos is None:
            out.add(form)
            continue
        for cand in rules[form[pos]]:
            body = "" if cand == "@" else cand
            nxt = form[:pos] + body + form[pos + 1 :]
            if sum(1 for c in nxt if c not in rules) > max_len:
                continue
            if len(nxt) > max_len + 4 * len(rules):
                continue
            if nxt not in seen:
                seen.add(nxt)
                todo.append(nxt)
    return {w for w in out if len(w) <= max_len}


def random_grammar(rng):
    nts = ["S"] + rng.sample(["A", "B", "C"], rng.randint(1, 2))
    terms = rng.sample(["a", "b", "c", "d"], rng.randint(2, 3))
    rules = {}
    for nt in nts:
        cands = []
        for _ in range(rng.randint(1, 3)):
            n = rng.randint(0, 3)
            if n == 0:
                cands.append("@")
            else:
                cands.append("".join(rng.choice(nts + terms) for _ in range(n)))
        # 去掉重复的候选式，保持与文本文法一致
        seen = []
        for c in cands:
            if c not in seen:
                seen.append(c)
        rules[nt] = seen
    return rules, nts, terms


def main():
    count = int(sys.argv[1]) if len(sys.argv) > 1 else 40
    seed = int(sys.argv[2]) if len(sys.argv) > 2 else 20260814
    rng = random.Random(seed)

    work = tempfile.mkdtemp(prefix="parser_fuzz_")
    binary = os.path.join(work, "parser")
    subprocess.check_call(
        ["g++", "-std=c++11", "-Wall", "-o", binary,
         os.path.join(ROOT, "Parser", "SyntacticParser.cpp")]
    )

    tried = used = strings = bad = 0
    while used < count:
        tried += 1
        if tried > count * 20:
            break
        rules, order, terms = random_grammar(rng)
        _, conflict = build_table(rules, order)
        if conflict:
            continue  # 不是LL(1)文法，表驱动分析器无需负责
        used += 1
        text = "    ".join("%s::=%s" % (nt, "|".join(rules[nt])) for nt in order)
        with open(os.path.join(work, "test3.txt"), "w") as fh:
            fh.write(text)
        lang = language(rules, order[0], MAX_LEN)
        words = [""]
        for n in range(1, MAX_LEN + 1):
            words += ["".join(w) for w in itertools.product(terms, repeat=n)]
        for w in words:
            strings += 1
            res = subprocess.run(
                [binary], cwd=work, input=w + "\n", stdout=subprocess.PIPE,
                stderr=subprocess.DEVNULL, universal_newlines=True, timeout=30,
            )
            last = res.stdout.strip().splitlines()[-1]
            got = "不是该文法的句子" not in last and last.endswith("是该文法的句子")
            want = w in lang
            if got != want:
                bad += 1
                print("FAIL grammar [%s] input [%s]: parser=%s derivation=%s"
                      % (text, w, "yes" if got else "no", "yes" if want else "no"))

    print("%d LL(1) grammars (of %d generated), %d strings checked, %d mismatches"
          % (used, tried, strings, bad))
    return 1 if bad else 0


if __name__ == "__main__":
    sys.exit(main())

